sys_script_include.script:
var AssignmentGroupUtils = Class.create();
AssignmentGroupUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    // Lab 7.4 method
    getNumberOfMembers: function() {
        var groupSysId = this.getParameter('sysparm_group'); 
        var gr = new GlideRecord('sys_user_grmember'); 
        gr.addQuery('group', groupSysId);
        gr.query();
        return String(gr.getRowCount()); 
    },

    // Lab 7.5 method
    getFirstAnalyst: function() {
        var groupSysId = this.getParameter('sysparm_group');
        var gr = new GlideRecord('sys_user_grmember');
        gr.addQuery('group', groupSysId);
        gr.orderBy('user'); // just grab the first alphabetically
        gr.query();

        if (gr.next()) {
            var userObj = {
                sys_id: gr.user.sys_id.toString(),
                name: gr.user.getDisplayValue()
            };
            return new global.JSON().encode(userObj); // must return stringified JSON
        }

        return new global.JSON().encode({ sys_id: '', name: '' });
    },

    type: 'AssignmentGroupUtils'
});
